import { readFileSync } from "node:fs";

import type { APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

type DocumentRef = { id: string; kind: string };

async function expectStatus(res: { status(): number; text(): Promise<string> }, status: number) {
  expect(res.status(), await res.text()).toBe(status);
}

async function submitVendorWithDocuments(member: APIRequestContext): Promise<{ vendorId: string; documents: DocumentRef[] }> {
  const name = uniqueName("Rev Vendor");
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, ".");
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: `${slug}@example.com` },
  });
  await expectStatus(created, 201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const documents: DocumentRef[] = [];
  for (const [kind, file] of [
    ["w9", "w9.txt"],
    ["insurance_certificate", "insurance_certificate.txt"],
    ["contract", "contract.txt"],
  ] as const) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    await expectStatus(upload, 201);
    documents.push((await upload.json()) as DocumentRef);
  }

  // Extraction runs in the background after upload.
  for (const doc of documents) {
    await expect
      .poll(async () => ((await (await member.get(`/api/documents/${doc.id}`)).json()) as { status: string }).status, {
        timeout: 60_000,
      })
      .toBe("extracted");
  }

  await expectStatus(await member.post(`/api/vendors/${vendorId}/submit`), 200);
  return { vendorId, documents };
}

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendorId, documents } = await submitVendorWithDocuments(member);

  const w9 = documents.find((d) => d.kind === "w9");
  expect(w9, "W-9 document was uploaded").toBeDefined();
  const extractionRes = await member.get(`/api/documents/${w9!.id}/extraction`);
  await expectStatus(extractionRes, 200);
  const extractionId = ((await extractionRes.json()) as { id: string }).id;

  // Act: reject without a note
  const withoutNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject" },
  });

  // Assert
  await expectStatus(withoutNote, 422);

  // Act: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  await expectStatus(withNote, 200);

  // Assert
  const vendorRes = await reviewer.get(`/api/vendors/${vendorId}`);
  await expectStatus(vendorRes, 200);
  expect(((await vendorRes.json()) as { status: string }).status).toBe("rejected");

  await expect
    .poll(async () => {
      const auditRes = await reviewer.get(`/api/vendors/${vendorId}/audit`);
      await expectStatus(auditRes, 200);
      const { items } = (await auditRes.json()) as { items: { action: string }[] };
      return items.map((item) => item.action);
    })
    .toContain("extraction.rejected");
});
